import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";   // ✅ ADD THIS

const Checkout = () => {
  const navigate = useNavigate();

  const [payment, setPayment] = useState("cod");

  // ✅ ADDRESS STATE
  const [address, setAddress] = useState({
    full: "",
    pincode: "",
    alt: ""
  });

  // ✅ SUBMIT FUNCTION (CONNECTED TO BACKEND)
  const handleSubmit = async (e) => {
    e.preventDefault();

    const user = JSON.parse(localStorage.getItem("user"));

    try {
      await axios.post("http://localhost:5000/place-order", {
        userId: user?._id,
        name: user?.name,
        address: address.full,
        pincode: address.pincode,
        altAddress: address.alt,
        paymentMethod: payment
      });

      alert("Order Placed ✅");
      navigate("/order-success");

    } catch (err) {
      alert("Order failed ❌");
    }
  };

  return (
    <div style={container}>
      <h1 style={{ textAlign: "center" }}>Checkout</h1>

      {/* PAYMENT OPTIONS */}
      <div style={card}>
        <h3>Select Payment Method</h3>

        <label style={radio}>
          <input
            type="radio"
            value="cod"
            checked={payment === "cod"}
            onChange={(e) => setPayment(e.target.value)}
          />
          Cash on Delivery
        </label>

        <label style={radio}>
          <input
            type="radio"
            value="upi"
            onChange={(e) => setPayment(e.target.value)}
          />
          UPI
        </label>

        <label style={radio}>
          <input
            type="radio"
            value="card"
            onChange={(e) => setPayment(e.target.value)}
          />
          Card Payment
        </label>
      </div>

      {/* COD FORM */}
      {payment === "cod" && (
        <div style={card}>
          <h3>Delivery Address</h3>

          <input
            placeholder="Full Address"
            value={address.full}
            onChange={(e) =>
              setAddress({ ...address, full: e.target.value })
            }
            style={input}
          />

          <input
            placeholder="Pincode"
            value={address.pincode}
            onChange={(e) =>
              setAddress({ ...address, pincode: e.target.value })
            }
            style={input}
          />

          <input
            placeholder="Alternate Address"
            value={address.alt}
            onChange={(e) =>
              setAddress({ ...address, alt: e.target.value })
            }
            style={input}
          />
        </div>
      )}

      {/* UPI FORM */}
      {payment === "upi" && (
        <div style={card}>
          <h3>Pay via UPI</h3>

          <button style={upiBtn}>Pay with GPay</button>
          <button style={upiBtn}>Pay with PhonePe</button>

          <input placeholder="Enter UPI ID" style={input} />
        </div>
      )}

      {/* CARD FORM */}
      {payment === "card" && (
        <div style={card}>
          <h3>Card Details</h3>

          <input placeholder="Card Number" style={input} />
          <input placeholder="Card Holder Name" style={input} />
          <input placeholder="Expiry (MM/YY)" style={input} />
          <input placeholder="CVV" type="password" style={input} />
        </div>
      )}

      {/* BUTTON */}
      <div style={bottomBar}>
        <button onClick={handleSubmit} style={checkoutBtn}>
          Place Order
        </button>
      </div>
    </div>
  );
};

/* ================= STYLES ================= */

const container = {
  padding: "20px",
  maxWidth: "600px",
  margin: "auto",
};

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "15px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
  marginBottom: "20px",
};

const input = {
  width: "100%",
  padding: "10px",
  margin: "10px 0",
  borderRadius: "8px",
  border: "1px solid #ccc",
};

const radio = {
  display: "block",
  margin: "10px 0",
};

const upiBtn = {
  width: "100%",
  padding: "10px",
  margin: "5px 0",
  border: "none",
  borderRadius: "8px",
  background: "#eee",
  cursor: "pointer",
};

const bottomBar = {
  position: "sticky",
  bottom: "0",
  background: "#fff",
  padding: "15px",
  boxShadow: "0 -5px 15px rgba(0,0,0,0.1)",
};

const checkoutBtn = {
  width: "100%",
  padding: "12px",
  border: "none",
  borderRadius: "25px",
  background: "#ff4f87",
  color: "white",
  fontWeight: "600",
  cursor: "pointer",
};

export default Checkout;
